{
  "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
  "contentVersion": "1.0.0.0",
  "parameters": {
    "capacity": {
      "type": "string",
      "metadata": {
        "description": "How many instances to run in the scale set"
      }
    },
    "location": {
      "type": "string",
      "defaultValue": "[resourceGroup().location]"
    }
  },
  "resources": [
    {
      "type": "Microsoft.Compute/virtualMachineScaleSets",
      "apiVersion": "2023-03-01",
      "name": "[concat('ssc-', parameters('location'))]",
      "location": "[parameters('location')]",
      "sku": {
        "name": "Standard_D2s_v5",
        "capacity": "[parameters('capacity')]"
      }
    }
  ]
}

{
  "languageVersion": "2.0",
  "parameters": {
    "ruleSettings": {
      "type": "array",
      "metadata": {
        "description": "Network rule details used by the deployment."
      }
    }
  },
  "variables": {
    "protocol": "[parameters('ruleSettings')[0]]",
    "port": "[parameters('ruleSettings')[1]]"
  },
  "outputs": {
    "appliedProtocol": {
      "type": "string",
      "value": "[variables('protocol')]"
    },
    "appliedPort": {
      "type": "int",
      "value": "[variables('port')]"
    }
  }
}

